#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "fibutil.h"
#include "version.h" /* generated by the Makefile into <build>/gen/ */

static flog_level_t g_level = FLOG_WARN;

static const char *const level_names[] = { "ERROR", "WARN", "INFO", "DEBUG" };

void flog_set_level(flog_level_t level)
{
    g_level = level;
}

void flog_init_from_env(void)
{
    const char *v = getenv("FIBTOOL_LOG");

    if (v == NULL)
        return;
    if (strcmp(v, "error") == 0)      g_level = FLOG_ERROR;
    else if (strcmp(v, "warn") == 0)  g_level = FLOG_WARN;
    else if (strcmp(v, "info") == 0)  g_level = FLOG_INFO;
    else if (strcmp(v, "debug") == 0) g_level = FLOG_DEBUG;
}

void flog_msg(flog_level_t level, const char *fmt, ...)
{
    va_list ap;

    if (level > g_level)
        return;

    fprintf(stderr, "[%s] ", level_names[level]);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
}

const char *fibutil_version(void)
{
    return FIBTOOL_VERSION_STRING;
}
